@import 'tailwindcss';
@import 'tw-animate-css';

@custom-variant dark (&:is(.dark *));

:root {
  /* ShaderGUI Course Player — dark-only tokens */
  --background:        #0d1117;
  --surface:           #161b22;
  --surface-raised:    #1c2230;
  --border:            #2a3244;
  --foreground:        #e6edf3;
  --muted-foreground:  #8b949e;
  --cyan:              #00e5ff;
  --cyan-dim:          #00b8cc;
  --amber:             #f59e0b;
  --amber-dim:         #b87a08;
  --green:             #3fb950;
  --red:               #f85149;
  --primary:           #00e5ff;
  --primary-foreground:#0d1117;
  --radius:            0.5rem;
}

@theme inline {
  --font-sans: 'Geist', 'Geist Fallback';
  --font-mono: 'Geist Mono', 'Geist Mono Fallback';
  --color-background:       var(--background);
  --color-surface:          var(--surface);
  --color-surface-raised:   var(--surface-raised);
  --color-foreground:       var(--foreground);
  --color-border:           var(--border);
  --color-muted-foreground: var(--muted-foreground);
  --color-primary:          var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-cyan:             var(--cyan);
  --color-cyan-dim:         var(--cyan-dim);
  --color-amber:            var(--amber);
  --color-amber-dim:        var(--amber-dim);
  --color-green:            var(--green);
  --color-red:              var(--red);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border;
  }
  html {
    @apply bg-background;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
  }
  ::-webkit-scrollbar { width: 4px; height: 4px; }
  ::-webkit-scrollbar-track { background: var(--surface); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
}

import type { Metadata } from 'next'
import { Geist, Geist_Mono } from 'next/font/google'
import { Analytics } from '@vercel/analytics/next'
import './globals.css'

const _geist = Geist({ subsets: ["latin"] });
const _geistMono = Geist_Mono({ subsets: ["latin"] });

export const metadata: Metadata = {
  title: 'ShaderGUI 课程播放器 · Module 01',
  description: 'Unity ShaderGUI 入门课程 — 从零构建参数化 Inspector 面板',
  generator: 'v0.app',
  icons: {
    icon: [
      {
        url: '/icon-light-32x32.png',
        media: '(prefers-color-scheme: light)',
      },
      {
        url: '/icon-dark-32x32.png',
        media: '(prefers-color-scheme: dark)',
      },
      {
        url: '/icon.svg',
        type: 'image/svg+xml',
      },
    ],
    apple: '/apple-icon.png',
  },
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body className="font-sans antialiased">
        {children}
        {process.env.NODE_ENV === 'production' && <Analytics />}
      </body>
    </html>
  )
}

"use client";

import { useEffect, useRef, useState } from "react";

/* ─── types ─────────────────────────────────────── */
interface Slide {
  slideId: string;
  title: string;
  kind: "concept" | "code";
  points: string[];
  hasCode: boolean;
}

interface MotionCue {
  id: number;
  label: string;
  x: number;
  y: number;
  visible: boolean;
}

interface Props {
  slide: Slide;
  motionCueCount: number;
  isPlaying: boolean;
  onTap: () => void;
}

/* ─── cue labels per kind ───────────────────────── */
const conceptCues = [
  ["前端工程层", "参数系统"],
  ["降低认知负担", "美术友好"],
  ["组织 · 解释 · 同步", "职责三层"],
];
const codeCues = [
  ["继承 ShaderGUI", "OnGUI 重写"],
  ["CustomEditor 绑定", "Shader 侧配置"],
  ["面板能力入口", "控制 OnGUI"],
];

/* ─── concept diagram ───────────────────────────── */
function ConceptDiagram({ slide, cues }: { slide: Slide; cues: MotionCue[] }) {
  return (
    <div className="flex flex-col items-center justify-center gap-4 w-full h-full select-none">
      {/* title badge */}
      <div className="flex items-center gap-2 mb-1">
        <span className="w-2 h-2 rounded-full bg-cyan-400 animate-pulse" />
        <span className="text-xs font-mono text-cyan-400 tracking-widest uppercase">
          概念层级
        </span>
      </div>
      <h2 className="text-xl font-bold text-foreground text-balance text-center px-4 leading-snug">
        {slide.title}
      </h2>

      {/* hierarchy boxes */}
      <div className="flex flex-col items-center gap-2 w-full max-w-xs mt-2">
        {slide.points.map((pt, i) => (
          <div
            key={i}
            className="relative w-full rounded-md border px-4 py-2.5 text-sm text-center transition-all"
            style={{
              borderColor: i === 0 ? "#00e5ff55" : i === 1 ? "#f59e0b55" : "#3fb95055",
              background:
                i === 0
                  ? "rgba(0,229,255,0.06)"
                  : i === 1
                  ? "rgba(245,158,11,0.06)"
                  : "rgba(63,185,80,0.06)",
              color: i === 0 ? "#00e5ff" : i === 1 ? "#f59e0b" : "#3fb950",
            }}
          >
            <span className="font-mono text-[11px] mr-2 opacity-50">
              {String(i + 1).padStart(2, "0")}
            </span>
            {pt}

            {/* motion cue pill */}
            {cues[i]?.visible && (
              <span
                className="absolute -right-1 -top-2 text-[9px] font-mono px-1.5 py-0.5 rounded-full border animate-bounce"
                style={{
                  borderColor: i === 0 ? "#00e5ff" : i === 1 ? "#f59e0b" : "#3fb950",
                  color: i === 0 ? "#00e5ff" : i === 1 ? "#f59e0b" : "#3fb950",
                  background: "#0d1117",
                }}
              >
                {conceptCues[i]?.[1]}
              </span>
            )}
          </div>
        ))}
      </div>

      {/* mental model arrow */}
      <div className="flex items-center gap-1 mt-1 opacity-40">
        <div className="w-8 h-px bg-muted-foreground" />
        <span className="text-[10px] font-mono text-muted-foreground">心智模型</span>
        <div className="w-8 h-px bg-muted-foreground" />
      </div>
    </div>
  );
}

/* ─── code structure diagram ────────────────────── */
function CodeDiagram({ slide, cues }: { slide: Slide; cues: MotionCue[] }) {
  const blocks = [
    {
      lang: "C#",
      file: "MyShaderGUI.cs",
      code: `public class MyShaderGUI\n  : ShaderGUI {\n  public override void\n    OnGUI(…) { … }\n}`,
      color: "#00e5ff",
    },
    {
      lang: "Shader",
      file: "MyShader.shader",
      code: `CustomEditor\n  "MyShaderGUI"`,
      color: "#f59e0b",
    },
  ];

  return (
    <div className="flex flex-col items-center justify-center gap-3 w-full h-full select-none px-3">
      <div className="flex items-center gap-2 mb-1">
        <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse" />
        <span className="text-xs font-mono text-amber-400 tracking-widest uppercase">
          代码结构
        </span>
      </div>
      <h2 className="text-xl font-bold text-foreground text-balance text-center leading-snug px-2">
        {slide.title}
      </h2>

      <div className="flex gap-3 w-full mt-1">
        {blocks.map((b, i) => (
          <div
            key={i}
            className="relative flex-1 rounded-lg border overflow-hidden"
            style={{ borderColor: b.color + "44", background: b.color + "08" }}
          >
            {/* file header */}
            <div
              className="flex items-center gap-1.5 px-3 py-1.5 border-b text-[10px] font-mono"
              style={{ borderColor: b.color + "33", color: b.color }}
            >
              <span
                className="w-1.5 h-1.5 rounded-full"
                style={{ background: b.color }}
              />
              {b.file}
            </div>
            {/* code body */}
            <pre
              className="px-3 py-2 text-[10px] leading-relaxed font-mono"
              style={{ color: b.color + "cc" }}
            >
              {b.code}
            </pre>
            {/* cue */}
            {cues[i]?.visible && (
              <div
                className="absolute bottom-1.5 right-1.5 text-[9px] font-mono px-1.5 py-0.5 rounded border animate-pulse"
                style={{
                  borderColor: b.color,
                  color: b.color,
                  background: "#0d1117",
                }}
              >
                {codeCues[i]?.[1]}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* connector arrow */}
      <div className="flex items-center gap-1">
        <div className="w-12 h-px bg-border" />
        <svg width="16" height="16" viewBox="0 0 16 16" className="text-muted-foreground">
          <path
            d="M2 8h10M9 5l3 3-3 3"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            fill="none"
          />
        </svg>
        <span className="text-[10px] font-mono text-muted-foreground">
          {cues[2]?.visible ? "✓ 面板能力入口" : "绑定关系"}
        </span>
        <div className="w-12 h-px bg-border" />
      </div>

      {/* points list */}
      <div className="w-full space-y-1 mt-1">
        {slide.points.map((pt, i) => (
          <div key={i} className="flex items-start gap-2">
            <span className="mt-0.5 w-1 h-1 rounded-full bg-amber-400 shrink-0" />
            <span className="text-[11px] text-muted-foreground leading-relaxed">{pt}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── main canvas ───────────────────────────────── */
export default function SlideCanvas({
  slide,
  motionCueCount,
  isPlaying,
  onTap,
}: Props) {
  const [cues, setCues] = useState<MotionCue[]>([]);
  const timerRef = useRef<ReturnType<typeof setTimeout>[]>([]);

  /* build cue list once per slide */
  useEffect(() => {
    setCues(
      Array.from({ length: motionCueCount }, (_, i) => ({
        id: i,
        label: slide.kind === "concept" ? conceptCues[i]?.[0] : codeCues[i]?.[0],
        x: 20 + i * 30,
        y: 20 + i * 20,
        visible: false,
      }))
    );
  }, [slide.slideId, motionCueCount]);

  /* reveal cues one-by-one while playing */
  useEffect(() => {
    timerRef.current.forEach(clearTimeout);
    timerRef.current = [];
    if (!isPlaying) return;
    cues.forEach((_, i) => {
      const t = setTimeout(
        () =>
          setCues((prev) =>
            prev.map((c, j) => (j === i ? { ...c, visible: true } : c))
          ),
        1400 + i * 1800
      );
      timerRef.current.push(t);
    });
    return () => timerRef.current.forEach(clearTimeout);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isPlaying, slide.slideId]);

  return (
    <div
      className="relative w-full flex-1 min-h-0 rounded-xl overflow-hidden cursor-pointer select-none"
      style={{
        background: "#161b22",
        border: "1px solid #2a3244",
      }}
      onClick={onTap}
      role="button"
      aria-label="点击播放/暂停"
    >
      {/* grid bg */}
      <svg
        className="absolute inset-0 w-full h-full opacity-[0.04] pointer-events-none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          <pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse">
            <path d="M 24 0 L 0 0 0 24" fill="none" stroke="#00e5ff" strokeWidth="0.5" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>

      {/* corner glow */}
      <div
        className="absolute top-0 left-0 w-32 h-32 rounded-full pointer-events-none"
        style={{
          background:
            slide.kind === "concept"
              ? "radial-gradient(circle, rgba(0,229,255,0.08) 0%, transparent 70%)"
              : "radial-gradient(circle, rgba(245,158,11,0.08) 0%, transparent 70%)",
        }}
      />

      {/* slide kind badge */}
      <div className="absolute top-3 left-3 flex items-center gap-1.5 z-10">
        <span
          className="px-2 py-0.5 rounded text-[9px] font-mono uppercase tracking-widest border"
          style={
            slide.kind === "concept"
              ? { borderColor: "#00e5ff44", color: "#00e5ff", background: "#00e5ff11" }
              : { borderColor: "#f59e0b44", color: "#f59e0b", background: "#f59e0b11" }
          }
        >
          {slide.kind === "concept" ? "概念" : "代码"}
        </span>
        <span className="text-[9px] font-mono text-muted-foreground">{slide.slideId}</span>
      </div>

      {/* tap-to-play hint */}
      {!isPlaying && (
        <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
          <div
            className="flex flex-col items-center gap-2 opacity-70"
          >
            <div
              className="w-12 h-12 rounded-full flex items-center justify-center border"
              style={{ borderColor: "#00e5ff55", background: "rgba(0,229,255,0.1)" }}
            >
              <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                <polygon points="7,4 16,10 7,16" fill="#00e5ff" />
              </svg>
            </div>
            <span className="text-[10px] font-mono text-cyan-400">点击播放</span>
          </div>
        </div>
      )}

      {/* content */}
      <div className="relative z-10 w-full h-full flex flex-col justify-center py-10 px-2">
        {slide.kind === "concept" ? (
          <ConceptDiagram slide={slide} cues={cues} />
        ) : (
          <CodeDiagram slide={slide} cues={cues} />
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

interface Props {
  isPlaying: boolean;
  onToggle: () => void;
  duration: number; // seconds
  slideId: string;
}

export default function AudioBar({ isPlaying, onToggle, duration, slideId }: Props) {
  const [progress, setProgress] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [showVol, setShowVol] = useState(false);
  const rafRef = useRef<number | null>(null);
  const startRef = useRef<number>(0);
  const accRef = useRef<number>(0); // accumulated seconds

  /* simulate playhead */
  useEffect(() => {
    if (isPlaying) {
      startRef.current = performance.now();
      const tick = () => {
        const elapsed = (performance.now() - startRef.current) / 1000 + accRef.current;
        const clamped = Math.min(elapsed, duration);
        setProgress(clamped / duration);
        if (clamped < duration) rafRef.current = requestAnimationFrame(tick);
      };
      rafRef.current = requestAnimationFrame(tick);
    } else {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      accRef.current += (performance.now() - startRef.current) / 1000;
    }
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [isPlaying, duration]);

  /* reset on slide change */
  useEffect(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    accRef.current = 0;
    startRef.current = 0;
    setProgress(0);
  }, [slideId]);

  const pct = Math.round(progress * 100);
  const elapsed = Math.round(progress * duration);
  const fmt = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;

  return (
    <div
      className="flex items-center gap-3 px-3 py-2 rounded-xl shrink-0"
      style={{ background: "#161b22", border: "1px solid #2a3244" }}
    >
      {/* play/pause */}
      <button
        onClick={onToggle}
        className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 transition-colors"
        style={{ background: isPlaying ? "#00e5ff22" : "#00e5ff33", border: "1px solid #00e5ff55" }}
        aria-label={isPlaying ? "暂停" : "播放"}
      >
        {isPlaying ? (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
            <rect x="2" y="2" width="3" height="8" rx="1" fill="#00e5ff" />
            <rect x="7" y="2" width="3" height="8" rx="1" fill="#00e5ff" />
          </svg>
        ) : (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
            <polygon points="3,2 10,6 3,10" fill="#00e5ff" />
          </svg>
        )}
      </button>

      {/* waveform + progress */}
      <div className="flex-1 flex flex-col gap-1 min-w-0">
        {/* waveform bars */}
        <div className="flex items-end gap-[2px] h-4 overflow-hidden">
          {Array.from({ length: 32 }, (_, i) => {
            const h = 4 + Math.abs(Math.sin(i * 0.7 + i * 0.3) * 12);
            const filled = i / 32 <= progress;
            return (
              <div
                key={i}
                style={{
                  width: 2,
                  height: h,
                  borderRadius: 1,
                  flexShrink: 0,
                  background: filled
                    ? isPlaying
                      ? "#00e5ff"
                      : "#00b8cc"
                    : "#2a3244",
                  transition: "background 0.2s",
                }}
              />
            );
          })}
        </div>
        {/* seek bar */}
        <input
          type="range"
          min={0}
          max={100}
          value={pct}
          onChange={(e) => {
            const v = Number(e.target.value) / 100;
            accRef.current = v * duration;
            startRef.current = performance.now();
            setProgress(v);
          }}
          className="w-full h-0.5 appearance-none rounded cursor-pointer"
          style={{
            background: `linear-gradient(to right, #00e5ff ${pct}%, #2a3244 ${pct}%)`,
            outline: "none",
          }}
          aria-label="播放进度"
        />
      </div>

      {/* time */}
      <span className="text-[10px] font-mono text-muted-foreground shrink-0 tabular-nums">
        {fmt(elapsed)}/{fmt(duration)}
      </span>

      {/* volume */}
      <div className="relative shrink-0">
        <button
          onClick={() => setShowVol((v) => !v)}
          className="w-6 h-6 flex items-center justify-center rounded"
          style={{ color: "#8b949e" }}
          aria-label="音量"
        >
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
            <path
              d="M2 5h2l3-3v10l-3-3H2V5z"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinejoin="round"
              fill="none"
            />
            {volume > 0.5 && (
              <path
                d="M9 3.5c1 .8 1.5 2 1.5 3.5S10 9.7 9 10.5"
                stroke="currentColor"
                strokeWidth="1.2"
                strokeLinecap="round"
                fill="none"
              />
            )}
          </svg>
        </button>
        {showVol && (
          <div
            className="absolute bottom-8 right-0 flex flex-col items-center gap-1 p-2 rounded-lg z-50"
            style={{ background: "#1c2230", border: "1px solid #2a3244" }}
          >
            <input
              type="range"
              min={0}
              max={1}
              step={0.05}
              value={volume}
              onChange={(e) => setVolume(Number(e.target.value))}
              className="h-16 appearance-none cursor-pointer"
              style={{
                writingMode: "vertical-lr",
                direction: "rtl",
                background: `linear-gradient(to top, #00e5ff ${volume * 100}%, #2a3244 ${volume * 100}%)`,
                width: 4,
                borderRadius: 2,
                outline: "none",
              }}
              aria-label="音量调节"
            />
            <span className="text-[9px] font-mono text-muted-foreground">
              {Math.round(volume * 100)}
            </span>
          </div>
        )}
      </div>

      {/* speed */}
      <button
        className="text-[9px] font-mono px-1.5 py-0.5 rounded border shrink-0"
        style={{ borderColor: "#2a3244", color: "#8b949e" }}
        aria-label="播放速度"
      >
        1×
      </button>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";

const subtitleMap: Record<string, string[]> = {
  p00: [
    "欢迎来到 ShaderGUI 入门模块……",
    "ShaderGUI 是 Shader 参数系统的前端工程层。",
    "它的核心目标是降低美术调参时的认知负担。",
    "职责分三层：组织参数、解释含义、同步状态。",
  ],
  p01: [
    "接下来看最小可行架构……",
    "C# 侧：继承 ShaderGUI 并重写 OnGUI 方法。",
    "Shader 侧：通过 CustomEditor 绑定自定义面板。",
    "所有高级面板能力都从控制 OnGUI 开始。",
  ],
};

interface Props {
  slideId: string;
  isPlaying: boolean;
}

export default function SubtitleBar({ slideId, isPlaying }: Props) {
  const lines = subtitleMap[slideId] ?? [];
  const [idx, setIdx] = useState(0);

  useEffect(() => {
    setIdx(0);
  }, [slideId]);

  useEffect(() => {
    if (!isPlaying || lines.length === 0) return;
    const t = setInterval(() => {
      setIdx((i) => (i + 1) % lines.length);
    }, 2800);
    return () => clearInterval(t);
  }, [isPlaying, slideId, lines.length]);

  return (
    <div
      className="flex items-center gap-2 px-3 py-2 rounded-lg shrink-0 min-h-[2.5rem]"
      style={{ background: "rgba(22,27,34,0.9)", border: "1px solid #2a3244" }}
    >
      <span
        className="w-1.5 h-1.5 rounded-full shrink-0 transition-colors"
        style={{ background: isPlaying ? "#00e5ff" : "#2a3244" }}
      />
      <p className="text-sm text-foreground leading-relaxed text-balance flex-1 font-sans">
        {lines[idx] ?? "——"}
      </p>
      <span className="text-[9px] font-mono text-muted-foreground shrink-0">
        {idx + 1}/{lines.length}
      </span>
    </div>
  );
}

"use client";

interface Props {
  total: number;
  current: number;
  onChange: (i: number) => void;
}

export default function NavDots({ total, current, onChange }: Props) {
  return (
    <div className="flex flex-col gap-2 items-center py-2">
      {Array.from({ length: total }, (_, i) => (
        <button
          key={i}
          onClick={() => onChange(i)}
          className="transition-all duration-200"
          style={{
            width: i === current ? 6 : 4,
            height: i === current ? 20 : 8,
            borderRadius: 3,
            background: i === current ? "#00e5ff" : "#2a3244",
          }}
          aria-label={`幻灯片 ${i + 1}`}
          aria-current={i === current ? "true" : undefined}
        />
      ))}
    </div>
