interface LogEntry {
  time: string;
  action: string;
  detail: string;
  kind: "info" | "success" | "error" | "warn";
}

function now() {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}:${String(d.getSeconds()).padStart(2, "0")}`;
}

/* ─── scan animation ─────────────────────────────── */
function ScanAnimation({ onDone }: { onDone: () => void }) {
  const [line, setLine] = useState(0);
  const count = 5;
  useEffect(() => {
    const t = setInterval(() => {
      setLine((l) => {
        if (l >= count - 1) { clearInterval(t); setTimeout(onDone, 300); return l; }
        return l + 1;
      });
    }, 220);
    return () => clearInterval(t);
  }, [onDone]);

  return (
    <div
      className="flex flex-col gap-2 p-4 rounded-xl w-full"
      style={{ background: "#161b22", border: "1px solid #2a3244" }}
    >
      <div className="flex items-center gap-2 mb-1">
        <div className="w-2 h-2 rounded-full bg-cyan-400 animate-ping" />
        <span className="text-xs font-mono text-cyan-400">正在扫描题库…</span>
      </div>
      {Array.from({ length: count }, (_, i) => (
        <div
          key={i}
          className="flex items-center gap-2 transition-all duration-200"
          style={{ opacity: i <= line ? 1 : 0.2 }}
        >
          <span className="text-[10px] font-mono text-muted-foreground w-6">{`Q${i + 1}`}</span>
          <div
            className="flex-1 h-1.5 rounded-full overflow-hidden"
            style={{ background: "#2a3244" }}
          >
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{
                width: i <= line ? "100%" : "0%",
                background: i <= line ? "#00e5ff" : "transparent",
              }}
            />
          </div>
          {i <= line && (
            <span className="text-[9px] font-mono text-green-400">✓</span>
          )}
        </div>
      ))}
    </div>
  );
}

