    setLog((l) => [...l.slice(-8), { time: now(), action, detail, kind }]);
  };

  /* init: shuffle bank */
  const initQuiz = () => {
    const shuffledBank = shuffle(RAW_QUESTIONS);
    const prepared = shuffledBank.map((q) => prepareQuestion(q).q);
    setQuestions(prepared);
    setQIdx(0);
    setSelected(null);
    setScore(0);
    setLog([]);
    addLog("shuffle-question-bank", `题库已打乱，共 ${shuffledBank.length} 题`, "info");
    setPhase("scanning");
  };

  useEffect(() => { initQuiz(); }, []);

  /* scroll log */
  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [log]);

