    if (phase !== "question" || !q) return;
    setSwapping(true);
    addLog("shuffle-options", "正在重排选项…", "warn");
    setTimeout(() => {
      const correctText = q.options[q.answer];
      const shuffledOpts = shuffle(q.options);
      const newAnswer = shuffledOpts.indexOf(correctText);
