/* ─── shuffle helper ─────────────────────────────── */
function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* ─── prepare question with shuffled options ─────── */
function prepareQuestion(q: Question): { q: Question; correctText: string } {
  const correctText = q.options[q.answer];
  const shuffledOpts = shuffle(q.options);
  const newAnswer = shuffledOpts.indexOf(correctText);
  return { q: { ...q, options: shuffledOpts, answer: newAnswer }, correctText };
}

